import React from 'react';
import { BrowserRouter as Router, Routes, Route, Link, useParams, useNavigate } from 'react-router-dom';

const dataAnggota = [
  {
    id: "anjani-astagina",
    nama: "Anjani Astagina",
    nim: "253140700111035",
    kelas: "T2-A • Group 5",
    jurusan: "Teknologi Informasi",
    domisili: "Malang",
    foto: "/images/anjani.jpg",
    tentang: "Seorang mahasiswa jurusan Teknologi Informasi dari Fakultas Vokasi Universitas Brawijaya asal Malang yang memiliki ketertarikan mendalam pada pengembangan antarmuka pengguna serta front-end development untuk aplikasi interaktif..."
  },
  {
    id: "tzurayya-aisyah",
    nama: "Tzurayya Aisyah",
    nim: "253140700111037",
    kelas: "T2-A • Group 5",
    jurusan: "Teknologi Informasi",
    domisili: "Bekasi",
    foto: "/images/tzurayya.jpeg", 
    tentang: "Halo! Saya merupakan mahasiswi program studi Teknologi Informasi di Universitas Brawijaya yang memiliki minat besar dalam bidang pengembangan aplikasi web serta Cyber Security..."
  },
  {
    id: "tabina-naila",
    nama: "Tabina Naila Griselda",
    nim: "253140701111031",
    kelas: "T2-A • Group 5",
    jurusan: "Teknologi Informasi",
    domisili: "Jombang",
    foto: "/images/tabina.jpeg",
    tentang: "Halo! Saya adalah mahasiswi program studi Teknologi Informasi Fakultas Vokasi di Universitas Brawijaya yang memiliki ketertarikan mendalam pada dunia pengembangan perangkat lunak..." 
  }
];

// --- 1. HALAMAN DAFTAR (HOME) ---
function Home() {
  return (
    <div className="max-w-7xl mx-auto py-12 px-6">
      <header className="mb-20 text-center animate-bounce-slow">
        <h1 className="text-6xl md:text-8xl font-black text-[#432C23] uppercase font-['Outfit']">
          GROUP FIVE<br/>
          <span className="text-[#A67B5B] italic">DIRECTORY</span>
        </h1>
      </header>
      
      <div className="grid grid-cols-1 md:grid-cols-3 gap-10">
        {dataAnggota.map((item) => (
          <Link to={`/profile/${item.id}`} key={item.id} className="group">
            <div className="bg-white border-4 border-[#5C4033] p-6 rounded-[2.5rem] shadow-[10px_10px_0px_#5C4033] transition-all duration-300 group-hover:-translate-y-2 group-hover:shadow-[15px_15px_0px_#A67B5B]">
              <div className="aspect-square rounded-3xl overflow-hidden mb-6 border-2 border-[#F5EFE6]">
                <img src={item.foto} className="w-full h-full object-cover grayscale group-hover:grayscale-0 transition-all duration-500" alt={item.nama} />
              </div>
              <h2 className="text-2xl font-black text-[#432C23] uppercase font-['Outfit']">{item.nama}</h2>
              <p className="text-[#A67B5B] font-bold mb-4">{item.nim}</p>
              <div className="py-2 bg-[#FAF7F0] text-center border-2 border-[#5C4033] font-bold rounded-xl group-hover:bg-[#5C4033] group-hover:text-white transition-colors">
                VIEW PROFILE →
              </div>
            </div>
          </Link>
        ))}
      </div>
    </div>
  );
}

// --- 2. HALAMAN DETAIL (PROFILE) ---
function ProfileDetail() {
  const { id } = useParams(); 
  const navigate = useNavigate();
  const user = dataAnggota.find((a) => a.id === id);

  if (!user) return <div className="text-center p-20">Data tidak ditemukan.</div>;

  return (
    <div className="max-w-4xl mx-auto py-12 px-6">
      <button onClick={() => navigate('/')} className="mb-8 font-bold border-2 border-[#5C4033] px-6 py-2 rounded-full bg-white shadow-[4px_4px_0px_#5C4033]">
        ← KEMBALI
      </button>

      <div className="bg-white border-4 border-[#5C4033] p-10 rounded-[2.5rem] shadow-[10px_10px_0px_#A67B5B] flex flex-col md:flex-row gap-10">
        <img src={user.foto} className="w-full md:w-1/3 rounded-3xl border-4 border-[#A67B5B] object-cover" alt={user.nama} />
        <div>
          <h1 className="text-5xl font-black text-[#432C23] uppercase font-['Outfit'] mb-2">{user.nama}</h1>
          <p className="text-xl font-bold text-[#A67B5B] mb-6">{user.nim}</p>
          <div className="grid grid-cols-2 gap-4">
             <div className="bg-[#F5EFE6] p-3 rounded-lg border-2 border-[#A67B5B]">
                <p className="text-[10px] font-bold text-[#A67B5B]">DOMISILI</p>
                <p className="font-bold">{user.domisili}</p>
             </div>
             <div className="bg-[#F5EFE6] p-3 rounded-lg border-2 border-[#A67B5B]">
                <p className="text-[10px] font-bold text-[#A67B5B]">KELAS</p>
                <p className="font-bold">{user.kelas}</p>
             </div>
          </div>
        </div>
      </div>

      <div className="mt-8 bg-[#FAF7F0] border-4 border-[#5C4033] p-8 rounded-[2.5rem] shadow-[8px_8px_0px_#5C4033]">
        <h3 className="font-black text-[#5C4033] uppercase border-b-2 border-[#EAD8C0] mb-4 pb-1 inline-block">Biography</h3>
        <p className="italic font-semibold text-[#432C23]">"{user.tentang}"</p>
      </div>
    </div>
  );
}

// --- 3. MAIN APP (ROUTING) ---
export default function App() {
  return (
    <Router>
      <div className="min-h-screen bg-[#F5EFE6] font-['Plus_Jakarta_Sans'] text-[#432C23] p-4 relative overflow-hidden">
        <style>
          {`
            @import url('https://fonts.googleapis.com/css2?family=Outfit:wght@900&family=Plus+Jakarta+Sans:wght@400;600;700;800&display=swap');
            @keyframes bounceSlow { 0%, 100% { transform: translateY(0); } 50% { transform: translateY(-10px); } }
            .animate-bounce-slow { animation: bounceSlow 3s infinite ease-in-out; }
          `}
        </style>
        
        <Routes>
          <Route path="/" element={<Home />} />
          <Route path="/profile/:id" element={<ProfileDetail />} />
        </Routes>
      </div>
    </Router>
  );
}
